fn main() { let bytes=std::fs::read(std::env::args().nth(1).unwrap()).unwrap(); let font=fc_sfnt::read_bytes(&bytes, &fc_sfnt::ReadOptions{font_index:Some(1),..Default::default()}).unwrap().fonts.remove(0); let report=fc_compile::export(&font, &|_| 0, &fc_compile::ExportOptions::default()).unwrap(); std::fs::write(std::env::args().nth(2).unwrap(),report.bytes).unwrap(); println!("warnings: {:?}",report.warnings); }